using System;
using System.Diagnostics;

// PROGRAM: Simulasi Perbedaan Waktu Eksekusi: Index Seek (B+ Tree) vs Table Scan (O(N))
const int TableSize = 1_000_000;
int[] clusteredKeys = new int[TableSize];
for (int i = 0; i < TableSize; i++) clusteredKeys[i] = i * 2; // Data terurut fisik

int target = 1_500_000; // Elemen yang dicari

// 1. Simulasi Table Scan (O(N) - Membaca seluruh data satu per satu)
var swScan = Stopwatch.StartNew();
bool foundScan = false;
for (int i = 0; i < TableSize; i++)
{
    if (clusteredKeys[i] == target)
    {
        foundScan = true;
        break;
    }
}
swScan.Stop();
Console.WriteLine($"[TABLE SCAN O(N)] {swScan.ElapsedTicks} ticks ({swScan.ElapsedMilliseconds} ms) | Found: {foundScan}");

// 2. Simulasi Index Seek (O(log N) - Binary Search B+ Tree traversal)
var swSeek = Stopwatch.StartNew();
int idx = Array.BinarySearch(clusteredKeys, target);
swSeek.Stop();
Console.WriteLine($"[INDEX SEEK O(log N)] {swSeek.ElapsedTicks} ticks ({swSeek.ElapsedMilliseconds} ms) | Found: {idx >= 0}");

Console.WriteLine($"\nIndex Seek {(double)swScan.ElapsedTicks / Math.Max(1, swSeek.ElapsedTicks):N0}x lebih cepat daripada Full Table Scan!");

