using System;

public class QueryExecutionPlanner
{
    public static string DetermineQueryOperator(bool hasIndexOnFilterColumn, bool isFilterSargable, bool isCovering)
    {
        if (!hasIndexOnFilterColumn || !isFilterSargable)
        {
            return "Full-Table-Scan";
        }

        return isCovering ? "Index-Seek-Covering" : "Index-Seek-With-KeyLookup";
    }

    public static void Main()
    {
        Console.WriteLine(DetermineQueryOperator(true, true, true));
        Console.WriteLine(DetermineQueryOperator(true, true, false));
        Console.WriteLine(DetermineQueryOperator(false, true, false));
    }
}
